def native_args(kernel,predicate):
    queries=kernel.get('native_query') if type(kernel) is dict else None
    if type(queries) is not list:
        return []
    for query in queries:
        args=query.get('arguments') if type(query) is dict and query.get('predicate')==predicate else None
        if type(args) is list and all(type(value) in (str,int,float,bool) for value in args):
            return list(args)
    return []


def add_time(facts,event,record,seen,unresolved):
    form=record.get('form'); start=record.get('start_date'); end=record.get('end_date'); date=record.get('date')
    if form=='ongoing_since' and type(start) is str:
        put(facts,'start_',[event,start],seen); return True
    if form=='closed_interval' and type(start) is str and type(end) is str:
        put(facts,'start_',[event,start],seen); put(facts,'end_',[event,end],seen); return True
    if form=='active_on_date' and type(date) is str:
        put(facts,'start_',[event,date],seen); put(facts,'end_',[event,date],seen); return True
    if form=='onset_only':
        unresolved.add('bare_onset_does_not_establish_later_enrollment_or_attendance')
    else:
        unresolved.add('timed_institution_fact_invalid')
    return False


def apply(inputs,premises):
    public=inputs.get('public_case',{}); observation=inputs.get('observation'); kernel=inputs.get('kernel',{})
    if type(observation) is not dict or type(observation.get('views')) is not list:
        return {'bindings':[],'unresolved':['student_service_observation_required']}
    witnesses=case_witnesses(public)
    if len(witnesses)==0:
        return {'bindings':[],'unresolved':['current_case_witness_unavailable']}
    outer=native_args(kernel,'s3306_c_10_A'); inner=native_args(kernel,'s3306_c_10_A_i')
    if len(outer)!=4 or type(outer[0]) is not str or type(outer[1]) is not str or type(outer[2]) is not str or type(outer[3]) is not str:
        return {'bindings':[],'unresolved':['concrete_native_service_query_unavailable']}
    target_service=outer[0]; target_employer=outer[1]; target_employee=outer[2]
    bindings=[]; unresolved=set(); status_names=('service_status','institution_status','enrollment_status','attendance_status')
    for view in observation.get('views'):
        if type(view) is not dict:
            unresolved.add('student_service_view_invalid'); continue
        faithful=True
        for name in status_names:
            if view.get(name)!='complete':
                faithful=False; unresolved.add(name+'_unread_or_ambiguous')
        services=view.get('services'); institutions=view.get('educational_institutions'); enrollments=view.get('enrollments'); attendance=view.get('attendance')
        if type(services) is not list or type(institutions) is not list or type(enrollments) is not list or type(attendance) is not list:
            unresolved.add('student_service_record_invalid'); continue
        candidates=[]
        for index,record in enumerate(services):
            if supported(record,public) and record.get('worker')==target_employee and record.get('employer')==target_employer:
                candidates.append(index)
        if len(candidates)==0:
            unresolved.add('queried_service_roles_not_witnessed')
            continue
        for chosen in candidates:
            facts=[]; seen=set(); local_faithful=faithful
            for index,record in enumerate(services):
                if not supported(record,public) or type(record.get('worker')) is not str or type(record.get('employer')) is not str:
                    local_faithful=False; continue
                event=target_service if index==chosen else 'observed_service_'+str(index)
                put(facts,'service_',[event],seen); put(facts,'agent_',[event,record.get('worker')],seen); put(facts,'patient_',[event,record.get('employer')],seen)
            for index,record in enumerate(institutions):
                if not supported(record,public) or type(record.get('institution')) is not str:
                    local_faithful=False; continue
                event='educational_institution_event_'+str(index); put(facts,'educational_institution_',[event],seen); put(facts,'agent_',[event,record.get('institution')],seen)
            for index,record in enumerate(enrollments):
                if not supported(record,public) or type(record.get('person')) is not str or type(record.get('institution')) is not str:
                    local_faithful=False; continue
                event='enrollment_event_'+str(index); put(facts,'enrollment_',[event],seen); put(facts,'agent_',[event,record.get('person')],seen); put(facts,'patient_',[event,record.get('institution')],seen)
                if not add_time(facts,event,record,seen,unresolved):
                    local_faithful=False
            for index,record in enumerate(attendance):
                if not supported(record,public) or type(record.get('person')) is not str or type(record.get('institution')) is not str:
                    local_faithful=False; continue
                event='attendance_event_'+str(index); put(facts,'attending_classes_',[event],seen); put(facts,'agent_',[event,record.get('person')],seen); put(facts,'location_',[event,record.get('institution')],seen)
                if not add_time(facts,event,record,seen,unresolved):
                    local_faithful=False
            if len(inner)==3 and type(inner[0]) is str and type(inner[1]) is str and type(inner[2]) is str:
                if inner[1]!=target_employer:
                    unresolved.add('native_institution_constraints_disagree')
                    local_faithful=False
            if not local_faithful:
                unresolved.add('student_service_extraction_unread_or_ambiguous')
            bindings.append({'inputs':{'facts':facts,'negative_givens':[],'extraction_status':'complete' if local_faithful else 'unread'},'witnesses':list(witnesses)})
    if len(bindings)==0:
        unresolved.add('no_coherent_student_service_binding')
    return {'bindings':bindings,'unresolved':sorted(unresolved)}
